    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Edge stripes act as targets for rays from the isolated marks.
    edge_colors = set()
    for r in range(h):
        if grid[r][0] != grid[0][0]:
            edge_colors.add(grid[r][0])
        if grid[r][-1] != grid[0][0]:
            edge_colors.add(grid[r][-1])
    for c in range(w):
        if grid[0][c] != grid[0][0]:
            edge_colors.add(grid[0][c])
        if grid[-1][c] != grid[0][0]:
            edge_colors.add(grid[-1][c])

    bg = max(set(v for row in grid for v in row),
             key=lambda v: sum(row.count(v) for row in grid))
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or color in edge_colors:
                continue
            out[r][c] = 4
            # Extend toward an edge stripe in the same row or column.
            directions = []
            if any(grid[r][x] == color for x in range(w)):
                if any(grid[r][x] in edge_colors for x in range(c + 1, w)):
                    directions.append((0, 1))
                if any(grid[r][x] in edge_colors for x in range(c)):
                    directions.append((0, -1))
            if any(grid[y][c] in edge_colors for y in range(h)):
                if any(grid[y][c] in edge_colors for y in range(r + 1, h)):
                    directions.append((1, 0))
                if any(grid[y][c] in edge_colors for y in range(r)):
                    directions.append((-1, 0))
            for dr, dc in directions[:1]:
