               if grid[r][c] not in (grid[0][0], 5)]
    for r, c, color in markers:
        candidates = []
        for dr, dc in ((0, 1), (0, -1), (1, 0), (-1, 0)):
            y, x = r + dr, c + dc
            while 0 <= y < h and 0 <= x < w:
